// ── Audit ───────────────────────────────────────────────────────────────────

const problems = []
const LIMITS = { episode_object: [40, 140], time_place_scope: [40, 140], mechanism: [40, 160], evidence_lens: [40, 160] }
const FORBIDDEN_WORDS = /\b(youtube|tiktok|instagram|facebook|microsoft|photoshop|illustrator|vimeo|twitch)\b/i
const UNSAFE_REFERENCE = /(?:\b[a-z][a-z0-9+.-]*:\S+|(?:^|[\s(])\/\/\S+|\bwww\.\S+|\b(?:[a-z0-9-]+\.)+[a-z]{2,}(?:\/\S*)?)/i
const ROUTING_DIRECTIVE = /\b(?:provider_id|model_id|engine_id)\b|\bprovider\s*(?::|=)\s*[^\s]+|\bmodel\s*(?::|=)\s*[^\s]+|\b(?:use|select)\s+(?:an?\s+|the\s+)?provider\b|\broute\s+(?:via|through)\s+(?:an?\s+|the\s+)?provider\b/i
const SENSITIVE = /(?:^|[\s,{;])(?:["']?(?:api(?:[_ -]?key)|secret|(?:access[_ -]?token)|token|bearer|account(?:[_ -]?id)|customer(?:[_ -]?id))["']?)\s*(?:[:=]\s*)/i

const ID_PATHS = new Set(['doc.id', 'doc.compatible_formula_ids[0]', 'doc.idea_axes[0].id'])
const walk = (value, path) => {
  if (typeof value === 'string') {
    if (ID_PATHS.has(path)) return
    const cap = path === 'doc.prompt_context' ? 12000 : 1000
    if (value.length < 1 || value.length > cap) problems.push(`${path}: length ${value.length} outside 1..${cap}`)
    if (FORBIDDEN_WORDS.test(value)) problems.push(`${path}: forbidden platform word`)
    if (UNSAFE_REFERENCE.test(value)) problems.push(`${path}: URI-like reference -> ${value}`)
    if (ROUTING_DIRECTIVE.test(value)) problems.push(`${path}: routing directive`)
    if (SENSITIVE.test(value)) problems.push(`${path}: credential-shaped assignment`)
    return
  }
  if (Array.isArray(value)) { value.forEach((item, index) => walk(item, `${path}[${index}]`)); return }
  if (value && typeof value === 'object') { for (const [key, item] of Object.entries(value)) walk(item, `${path}.${key}`) }
}
walk(doc, 'doc')

if (doc.subjects.length !== 50) problems.push(`subjects: ${doc.subjects.length} != 50`)
if (new Set(doc.subjects).size !== 50) problems.push('subjects: duplicates present')
if (coverage_profiles.length !== 50) problems.push(`coverage_profiles: ${coverage_profiles.length} != 50`)

const fullTuples = new Set()
const objectMechanism = new Set()
const declared = {
  episode_object: new Set(doc.episode_objects), time_place_scope: new Set(doc.time_place_scopes),
  mechanism: new Set(doc.mechanisms), evidence_lens: new Set(doc.evidence_lenses),
}
for (const profile of coverage_profiles) {
  if (profile.tuples.length !== 20) problems.push(`${profile.subject}: ${profile.tuples.length} tuples != 20`)
  const objects = new Set(profile.tuples.map(t => t.episode_object))
  const mechanisms = new Set(profile.tuples.map(t => t.mechanism))
  if (objects.size !== profile.tuples.length) problems.push(`${profile.subject}: duplicate episode_object within subject`)
  if (mechanisms.size !== profile.tuples.length) problems.push(`${profile.subject}: duplicate mechanism within subject`)
  for (const tuple of profile.tuples) {
    for (const key of KEYS) {
      const value = tuple[key]
      if (!declared[key].has(value)) problems.push(`${profile.subject}: ${key} not declared`)
      const [min, max] = LIMITS[key]
      if (value.length < min || value.length > max) problems.push(`${profile.subject}: ${key} length ${value.length} outside ${min}..${max} -> ${value}`)
      if (/\s\s|^\s|\s$/.test(value)) problems.push(`${profile.subject}: ${key} whitespace problem`)
    }
    const full = KEYS.map(key => tuple[key]).join(' || ')
    if (fullTuples.has(full)) problems.push(`duplicate full tuple: ${full}`)
    fullTuples.add(full)
    const pair = `${tuple.episode_object} || ${tuple.mechanism}`
    if (objectMechanism.has(pair)) problems.push(`duplicate object|mechanism pair: ${pair}`)
    objectMechanism.add(pair)
  }
}
if (doc.prompt_context.length > 1500) problems.push(`prompt_context length ${doc.prompt_context.length} > 1500`)
for (const tag of doc.youtube_tags_hint) {
  if (tag.includes('#')) problems.push(`youtube_tags_hint contains hash: ${tag}`)
  const words = tag.trim().split(/\s+/).length
  if (words < 1 || words > 4) problems.push(`youtube_tags_hint word count ${words}: ${tag}`)
}
for (const list of ['episode_objects', 'time_place_scopes', 'mechanisms', 'evidence_lenses']) {
  if (doc[list].length > 2000) problems.push(`${list}: ${doc[list].length} > 2000`)
}

mkdirSync(path.dirname(OUT), { recursive: true })
writeFileSync(OUT, JSON.stringify(doc, null, 2) + '\n', 'utf8')

console.log('subjects              ', doc.subjects.length)
console.log('coverage_profiles     ', coverage_profiles.length)
console.log('tuples total          ', coverage_profiles.reduce((sum, p) => sum + p.tuples.length, 0))
console.log('episode_objects       ', doc.episode_objects.length)
console.log('time_place_scopes     ', doc.time_place_scopes.length)
console.log('mechanisms            ', doc.mechanisms.length)
console.log('evidence_lenses       ', doc.evidence_lenses.length)
console.log('unique full tuples    ', fullTuples.size)
console.log('unique object|mech    ', objectMechanism.size)
console.log('prompt_context chars  ', doc.prompt_context.length)
console.log('bytes written         ', statSync(OUT).size)
console.log(problems.length === 0 ? 'AUDIT OK' : `AUDIT FAILURES (${problems.length}):`)
for (const problem of problems) console.log('  -', problem)
